insert into public.hub_chk_answers(firm_id, code, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at)
  select firm_id, t.c, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at from public.hub_chk_answers, (values ('DM05','DM33'),('FA09','FA19'),('FA09','FA20')) as t(f,c) where code=t.f and answer in ('yes','na') on conflict do nothing;
